use std::collections::HashSet;

use crate::ast::{
    Program, Statement, ImportNode, ImportSpecifier, ExportNode,
    FunctionDefNode, AssignmentNode, Expr, BinaryOp, QuantityNode
};
use super::{CodeGenerator, CodegenError};

pub struct PythonTranspiler;

impl CodeGenerator for PythonTranspiler {
    fn generate_program(&self, program: &Program) -> Result<String, CodegenError> {
        let mut out = String::from(concat!(
            "# Generated by PhysureScript (PHS) Compiler v", env!("CARGO_PKG_VERSION"), "\n",
            "import math\n",
            "from physure import Q_, Quantity, PhyEquation, PhyFunction, phy_function\n\n",
            "try:\n",
            "    from physure.builtins import vector, gradient, trapz, solve, deriv, integral\n",
            "except ImportError:\n",
            "    def vector(*args): return list(args)\n\n"
        ));
        let mut known_bools: HashSet<String> = HashSet::new();

        for stmt in &program.statements {
            match stmt {
                Statement::Assignment(node) => {
                    if super::is_definitely_bool(&node.value, &known_bools) {
                        known_bools.insert(node.name.clone());
                    } else {
                        known_bools.remove(&node.name);
                    }
                    let stmt_str = self.generate_assignment(node)?;
                    out.push_str(&stmt_str);
                    out.push('\n');
                    out.push_str(&format!("print(f\"{}: {{{}}}\")\n", node.name, sanitize_identifier(&node.name)));
                }
                Statement::Expr(expr) => {
                    match super::as_assert_call(expr, &known_bools) {
                        Some(super::AssertShape::Bool { condition }) => {
                            let cond_code = self.generate_expr(condition)?;
                            out.push_str(&format!("if not ({}): raise AssertionError(\"assertion failed\")\n", cond_code));
                        }
                        Some(super::AssertShape::BoolWithMessage { condition, message }) => {
                            let cond_code = self.generate_expr(condition)?;
                            let msg_code = self.generate_expr(message)?;
                            out.push_str(&format!("if not ({}): raise AssertionError({})\n", cond_code, msg_code));
                        }
                        Some(super::AssertShape::Quantities { kind, actual, expected }) => {
                            let a_code = self.generate_expr(actual)?;
                            let b_code = self.generate_expr(expected)?;
                            let line = if kind == "assert" {
                                format!(
                                    "if not ({a}).approx_eq({b}, 1e-9, 1e-12): raise AssertionError(f'assert failed: {{{a}}} != {{{b}}}')",
                                    a = a_code, b = b_code
                                )
                            } else {
                                format!(
                                    "if not ({a}).exact_eq({b}): raise AssertionError(f'exact_assert failed: {{{a}}} != {{{b}}}')",
                                    a = a_code, b = b_code
                                )
                            };
                            out.push_str(&line);
                            out.push('\n');
                        }
                        None => {
                            let expr_str = self.generate_expr(expr)?;
                            out.push_str(&format!("print({})\n", expr_str));
                        }
                    }
                }
                _ => {
                    let stmt_str = self.generate_statement(stmt)?;
                    if !stmt_str.is_empty() {
                        out.push_str(&stmt_str);
                        out.push('\n');
                    }
                }
            }
        }

        Ok(out)
    }
}

fn sanitize_identifier(name: &str) -> String {
    name.replace('≈', "_approx")
        .replace('±', "_pm")
        .replace('σ', "_sigma")
        .replace('π', "pi")
        .replace('Δ', "delta")
        .replace('μ', "micro")
        .replace('λ', "lambda")
        .replace('θ', "theta")
        .replace('Ω', "omega")
}

impl PythonTranspiler {
    fn generate_statement(&self, stmt: &Statement) -> Result<String, CodegenError> {
        match stmt {
            Statement::Import(node) => self.generate_import(node),
            Statement::Export(node) => self.generate_export(node),
            Statement::FunctionDef(node) => self.generate_function_def(node),
            Statement::Assignment(node) => self.generate_assignment(node),
            Statement::Expr(expr) => self.generate_expr(expr),
            Statement::Return(expr) => Ok(format!("return {}", self.generate_expr(expr)?)),
            Statement::GuardReturn { cond, value } => {
                Ok(format!("if {}: return {}", self.generate_expr(cond)?, self.generate_expr(value)?))
            }
            Statement::While { cond, body, .. } => {
                let cond_str = self.generate_expr(cond)?;
                let mut lines = Vec::new();
                for stmt in body {
                    let stmt_code = self.generate_statement(stmt)?;
                    for line in stmt_code.lines() {
                        lines.push(format!("    {}", line));
                    }
                }
                if lines.is_empty() {
                    lines.push("    pass".to_string());
                }
                Ok(format!("while {}:\n{}", cond_str, lines.join("\n")))
            }
        }
    }
    
    fn generate_import(&self, node: &ImportNode) -> Result<String, CodegenError> {
        let py_path = node.path.replace("/", ".");
        if py_path == "calc" || py_path == "builtins" {
            return Ok(format!("# Builtin module '{}' imported", py_path));
        }
        let module = format!("physure.{}", py_path);
        
        match &node.specifier {
            ImportSpecifier::Wildcard => Ok(format!("from {} import *", module)),
            ImportSpecifier::Symbols(syms) => {
                let mut sym_strs = Vec::new();
                for sym in syms {
                    if let Some(alias) = &sym.alias {
                        sym_strs.push(format!("{} as {}", sym.name, alias));
                    } else {
                        sym_strs.push(sym.name.clone());
                    }
                }
                Ok(format!("from {} import {}", module, sym_strs.join(", ")))
            }
            ImportSpecifier::ModuleAlias(alias) => {
                Ok(format!("import {} as {}", module, alias))
            }
        }
    }
    
    fn generate_export(&self, node: &ExportNode) -> Result<String, CodegenError> {
        Ok(format!("__all_exports__[\"{}\"] = {}", node.export_name, node.symbol))
    }
    
    fn generate_function_def(&self, node: &FunctionDefNode) -> Result<String, CodegenError> {
        let params = node.params.join(", ");
        let params_list = format!("{:?}", node.params);
        let last_idx = node.body_stmts.len().saturating_sub(1);
        let mut lines = Vec::new();
        for (i, stmt) in node.body_stmts.iter().enumerate() {
            let stmt_code = self.generate_statement(stmt)?;
            if i == last_idx {
                if let Statement::Expr(ref e) = stmt {
                    lines.push(format!("    return {}", self.generate_expr(e)?));
                } else {
                    lines.push(format!("    {}", stmt_code));
                }
            } else {
                lines.push(format!("    {}", stmt_code));
            }
        }
        Ok(format!("@phy_function(name=\"{}\", params={})\ndef {}({}):\n{}", node.name, params_list, node.name, params, lines.join("\n")))
    }
    
    fn generate_assignment(&self, node: &AssignmentNode) -> Result<String, CodegenError> {
        let val_str = self.generate_expr(&node.value)?;
        if val_str.starts_with('"') && val_str.contains('=') {
            Ok(format!("{} = PhyEquation({})", sanitize_identifier(&node.name), val_str))
        } else {
            Ok(format!("{} = {}", sanitize_identifier(&node.name), val_str))
        }
    }
    
    fn generate_expr(&self, expr: &Expr) -> Result<String, CodegenError> {
        match expr {
            Expr::Quantity(node) => self.generate_quantity(node),
            Expr::Str(text) => {
                // Not an f-string: `{2 m + 3 m}` is PHS, not Python, so each interpolated
                // expression is transpiled on its own and concatenated.
                let parts = super::split_interpolated(text);
                let mut pieces = Vec::new();
                for part in &parts {
                    match part {
                        super::StrPart::Text(t) => pieces.push(format!("{:?}", t)),
                        super::StrPart::Expr(e) => pieces.push(format!("str({})", self.generate_expr(e)?)),
                    }
                }
                Ok(if pieces.len() == 1 { pieces.remove(0) } else { format!("({})", pieces.join(" + ")) })
            }
            Expr::Bool(b) => Ok(if *b { "True" } else { "False" }.to_string()),
            Expr::Identifier(name) => {
                if name.starts_with('`') || name.contains('\n') {
                    let clean = name.trim_matches('`').trim();
                    Ok(format!("\"\"\"{}\"\"\"", clean))
                } else {
                    Ok(sanitize_identifier(name))
                }
            }
            Expr::BinaryOp { op, left, right } => {
                let l_str = self.generate_expr(left)?;
                if *op == BinaryOp::Convert {
                    let unit_str = super::expr_to_unit_string(right);
                    Ok(format!("{}.to(\"{}\")", l_str, unit_str))
                } else if *op == BinaryOp::Pow {
                    if let Expr::Quantity(q) = &**right {
                        if q.unit.is_none() || q.unit.as_deref() == Some("") {
                            return Ok(format!("({} ** {:?})", l_str, q.magnitude));
                        }
                    }
                    let r_str = self.generate_expr(right)?;
                    Ok(format!("({} ** {})", l_str, r_str))
                } else {
                    let r_str = self.generate_expr(right)?;
                    let op_str = match op {
                        BinaryOp::Add => "+",
                        BinaryOp::Sub => "-",
                        BinaryOp::Mul => "*",
                        BinaryOp::Div => "/",
                        BinaryOp::Pow => unreachable!(),
                        BinaryOp::Convert => unreachable!(),
                        BinaryOp::Range => return Err(super::range_is_not_transpilable()),
                    };
                    Ok(format!("({} {} {})", l_str, op_str, r_str))
                }
            }
            Expr::FunctionCall { name, args, kwargs } => {
                if let Some((op_sym, l, r)) = super::as_comparison_op(expr) {
                    let l_str = self.generate_expr(l)?;
                    let r_str = self.generate_expr(r)?;
                    return Ok(format!("({} {} {})", l_str, op_sym, r_str));
                }
                if let Some(logical) = super::as_logical_op(expr) {
                    return Ok(match logical {
                        super::LogicalOp::Not(x) => format!("(not {})", self.generate_expr(x)?),
                        super::LogicalOp::And(l, r) => format!("({} and {})", self.generate_expr(l)?, self.generate_expr(r)?),
                        super::LogicalOp::Or(l, r) => format!("({} or {})", self.generate_expr(l)?, self.generate_expr(r)?),
                    });
                }
                if (name == "assert" || name == "exact_assert") && kwargs.is_empty() && matches!(args.len(), 1 | 2) {
                    return Err(CodegenError::Generic(format!(
                        "'{}' can only be used as a standalone statement, not nested inside an expression",
                        name
                    )));
                }
                let mut arg_strs = Vec::new();
                for (i, arg) in args.iter().enumerate() {
                    let arg_s = self.generate_expr(arg)?;
                    if name == "format" && i == 1 && !arg_s.starts_with('"') {
                        arg_strs.push(format!("\"{}\"", arg_s));
                    } else {
                        arg_strs.push(arg_s);
                    }
                }
                for (kwarg_name, kwarg_expr) in kwargs {
                    let kwarg_s = self.generate_expr(kwarg_expr)?;
                    arg_strs.push(format!("{}={}", sanitize_identifier(kwarg_name), kwarg_s));
                }
                Ok(format!("{}({})", sanitize_identifier(name), arg_strs.join(", ")))
            }
            Expr::ForExpr { var, iterable, body } => {
                let it_str = self.generate_expr(iterable)?;
                let body_str = self.generate_expr(body)?;
                Ok(format!("[{} for {} in {}]", body_str, sanitize_identifier(var), it_str))
            }
        }
    }
    
    fn generate_quantity(&self, node: &QuantityNode) -> Result<String, CodegenError> {
        if let Some(reason) = node.asymmetric_refusal() {
            return Err(CodegenError::Generic(reason));
        }
        let unit_str = node.unit.as_deref().unwrap_or("");
        let unc_str = if let Some(unc) = node.uncertainty {
            format!(", uncertainty={:?}", unc)
        } else {
            String::new()
        };
        Ok(format!("Q_({:?}, \"{}\"{})", node.magnitude, unit_str, unc_str))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ast::{ImportSymbol, Program, Statement, FunctionDefNode, Expr, QuantityNode, BinaryOp, ImportNode, ImportSpecifier};

    #[test]
    fn test_transpile_quantity_with_uncertainty() {
        let tp = PythonTranspiler;
        let q = QuantityNode {
            magnitude: 5.0,
            uncertainty: Some(0.1),
            uncertainty_lower: None,
            is_sigma: false,
            unit: Some("m".to_string()),
        };
        let res = tp.generate_quantity(&q).unwrap();
        assert_eq!(res, "Q_(5.0, \"m\", uncertainty=0.1)");
    }

    #[test]
    fn test_transpile_function_def_and_import() {
        let tp = PythonTranspiler;
        
        let import_node = ImportNode {
            path: "physics/constants".to_string(),
            specifier: ImportSpecifier::Symbols(vec![
                ImportSymbol { name: "g".to_string(), alias: None }
            ]),
        };
        
        let fn_node = FunctionDefNode {
            name: "foo".to_string(),
            params: vec!["a".to_string(), "b".to_string()],
            param_units: vec![None, None],
            body_stmts: vec![Statement::Expr(Expr::BinaryOp {
                op: BinaryOp::Mul,
                left: Box::new(Expr::Identifier("a".to_string())),
                right: Box::new(Expr::Identifier("b".to_string())),
            })],
            body_lines: vec![],
            decorators: Vec::new(),
            doc: None,
        };

        let prog = Program {
            statements: vec![
                Statement::Import(import_node),
                Statement::FunctionDef(fn_node),
            ],
            lines: vec![],
        };

        let res = tp.generate_program(&prog).unwrap();
        assert!(res.contains("from physure.physics.constants import g"));
        assert!(res.contains("def foo(a, b):\n    return (a * b)"));
    }

    #[test]
    fn transpiles_bool_literals_python() {
        let tp = PythonTranspiler;
        assert_eq!(tp.generate_expr(&Expr::Bool(true)).unwrap(), "True");
        assert_eq!(tp.generate_expr(&Expr::Bool(false)).unwrap(), "False");
    }

    #[test]
    fn transpiles_assert_call_to_a_python_conditional_raise() {
        // Python's `assert` statement is removed by `python -O`; the design requires an
        // explicit `if not ...: raise AssertionError(...)` instead so `-O` can't disable it.
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("assert(1.0 km, 1000.0 m)").unwrap();
        let code = tp.generate_program(&program).unwrap();
        assert!(code.contains("if not"), "expected a conditional raise:\n{code}");
        assert!(code.contains("raise AssertionError"), "expected AssertionError:\n{code}");
        assert!(!code.contains("\nassert "), "must not emit a removable `assert` statement:\n{code}");
        assert!(code.contains(".approx_eq("), "expected approx_eq call:\n{code}");
    }

    #[test]
    fn transpiles_exact_assert_call_to_equality_assert() {
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("exact_assert(5.0 m, 5.0 m)").unwrap();
        let code = tp.generate_program(&program).unwrap();
        assert!(code.contains("if not") && code.contains(".exact_eq("), "expected an exact_eq conditional raise:\n{code}");
        assert!(!code.contains("\nassert "), "must not emit a removable `assert` statement:\n{code}");
    }

    #[test]
    fn transpiled_quantity_assert_is_valid_python_syntax() {
        // A regression test for a real bug: the assert-failure message f-string used to
        // nest double-quoted unit strings (`Q_(1.0, "km")`) inside a double-quoted outer
        // f-string, which is a SyntaxError before Python 3.12 (this project supports
        // 3.11+). Compiling (not running) the generated code is enough to catch this
        // class of bug without needing the `physure` package importable.
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("assert(1.0 km, 1000.0 m)").unwrap();
        let code = tp.generate_program(&program).unwrap();

        let python = if cfg!(windows) { "python" } else { "python3" };
        let output = match std::process::Command::new(python)
            .args(["-c", "import sys; compile(sys.stdin.read(), '<generated>', 'exec')"])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .and_then(|mut child| {
                use std::io::Write;
                child.stdin.take().unwrap().write_all(code.as_bytes())?;
                child.wait_with_output()
            }) {
            Ok(o) => o,
            Err(_) => {
                eprintln!("skipping: no python interpreter available");
                return;
            }
        };
        assert!(
            output.status.success(),
            "generated Python failed to compile:\n{}\nstderr: {}",
            code,
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn rejects_assert_used_as_a_nested_expression_py() {
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("x = assert(1.0 m, 1.0 m)").unwrap();
        assert!(tp.generate_program(&program).is_err());
    }

    #[test]
    fn transpiles_logical_operators_python() {
        let tp = PythonTranspiler;
        let not_expr = Expr::FunctionCall { name: "op_not".to_string(), args: vec![Expr::Bool(true)], kwargs: vec![] };
        assert_eq!(tp.generate_expr(&not_expr).unwrap(), "(not True)");
        let and_expr = Expr::FunctionCall { name: "op_and".to_string(), args: vec![Expr::Bool(true), Expr::Bool(false)], kwargs: vec![] };
        assert_eq!(tp.generate_expr(&and_expr).unwrap(), "(True and False)");
        let or_expr = Expr::FunctionCall { name: "op_or".to_string(), args: vec![Expr::Bool(false), Expr::Bool(true)], kwargs: vec![] };
        assert_eq!(tp.generate_expr(&or_expr).unwrap(), "(False or True)");
    }

    #[test]
    fn transpiles_one_argument_bool_assert_python() {
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("assert(1.0 m > 0.0 m)").unwrap();
        let code = tp.generate_program(&program).unwrap();
        assert!(code.contains("if not") && code.contains("raise AssertionError(\"assertion failed\")"), "{code}");
    }

    #[test]
    fn transpiles_bool_assert_with_message_python() {
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("assert(1.0 m > 2.0 m, \"too small\")").unwrap();
        let code = tp.generate_program(&program).unwrap();
        assert!(code.contains("raise AssertionError(\"too small\")"), "{code}");
    }

    #[test]
    fn rejects_one_argument_assert_nested_in_an_expression_py() {
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("x = assert(1.0 m > 0.0 m)").unwrap();
        assert!(tp.generate_program(&program).is_err());
    }

    #[test]
    fn named_bool_assignment_feeds_a_later_assert_python() {
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("ok = 1.0 m > 0.0 m\nassert(ok, \"should hold\")").unwrap();
        let code = tp.generate_program(&program).unwrap();
        assert!(
            code.contains("raise AssertionError(\"should hold\")"),
            "expected the Bool+message shape, not a Quantity assert:\n{code}"
        );
    }

    #[test]
    fn an_assert_with_an_unclassified_condition_errors_instead_of_emitting_broken_python() {
        // `is_ready(x)` isn't a literal, comparison, logical op, or tracked-bool identifier,
        // so `is_definitely_bool` correctly can't promise it's Bool -- this must produce a
        // clear CodegenError, not silently fall through to `print(assert(is_ready(x)))`
        // (a Python SyntaxError, since `assert` is a keyword there, not a callable).
        let tp = PythonTranspiler;
        let program = crate::parser::parse_phs("fn is_ready(x) = x > 0\nassert(is_ready(v))").unwrap();
        let result = tp.generate_program(&program);
        assert!(result.is_err(), "expected a CodegenError, got: {result:?}");
    }

    #[test]
    fn test_transpile_for_expr_and_while_stmt_python() {
        let tp = PythonTranspiler;
        let for_expr = Expr::ForExpr {
            var: "x".to_string(),
            iterable: Box::new(Expr::Identifier("items".to_string())),
            body: Box::new(Expr::Identifier("x".to_string())),
        };
        let code_for = tp.generate_expr(&for_expr).unwrap();
        assert_eq!(code_for, "[x for x in items]");

        let while_stmt = Statement::While {
            cond: Expr::Identifier("flag".to_string()),
            body: vec![Statement::Assignment(AssignmentNode {
                name: "i".to_string(),
                value: Expr::Identifier("1".to_string()),
                decorators: Vec::new(),
            })],
            body_lines: vec![],
        };
        let code_while = tp.generate_statement(&while_stmt).unwrap();
        assert_eq!(code_while, "while flag:\n    i = 1");
    }
}
